)


def domain_name(value):
    domain = value.strip().lower().removesuffix(".").removeprefix("www.")
    labels = domain.split(".")
    if len(domain) > 253 or len(labels) < 2 or any(not HOST_LABEL.fullmatch(x) for x in labels):
